"""Verify rapidocr engine works and returns real ingredient text."""
import requests, sys, time

BASE = "http://localhost:8000/api/v1"

# Use the same PNG generated by test_ocr_real.py
from PIL import Image, ImageDraw, ImageFont
import io

img = Image.new("RGB", (800, 300), color="white")
draw = ImageDraw.Draw(img)
font = None
for path in ["C:/Windows/Fonts/msyh.ttc", "C:/Windows/Fonts/simhei.ttf"]:
    try:
        font = ImageFont.truetype(path, 28)
        break
    except Exception:
        continue
if font is None:
    font = ImageFont.load_default()

lines = [
    "配料表",
    "配料：黄芪5g，枸杞3g，山药10g，",
    "柠檬酸0.5g，E150（焦糖色）0.1g，",
    "E330（柠檬酸）2g",
]
y = 30
for line in lines:
    draw.text((40, y), line, fill="black", font=font)
    y += 50

buf = io.BytesIO()
img.save(buf, format="PNG")
buf.seek(0)

files = {"file": ("label.png", buf, "image/png")}
print("Calling /ingredients/ocr (first call downloads model, ~30s)...")
t0 = time.time()
r = requests.post(f"{BASE}/ingredients/ocr", files=files, timeout=300)
elapsed = time.time() - t0
d = r.json()
print(f"OCR: HTTP {r.status_code}, {elapsed:.1f}s")
print("success:", d.get("success"))
print("message:", (d.get("message") or "")[:120])
if d.get("text"):
    print("text:", d["text"])
    names = [i["name"] for i in (d.get("ingredients") or [])]
    print("ingredients:", names)
if d.get("success") and d.get("text"):
    print("PASS: real OCR text returned")
else:
    print("FAIL: OCR not working")
    sys.exit(1)
